    stop = {
        "the", "and", "for", "with", "from", "that", "this", "what", "how", "why", "when",
        "where", "into", "about", "using", "use", "latest", "official", "docs", "guide",
        "请", "什么", "如何", "最新", "资料", "搜索", "查询", "官网", "文档",
    }
